@Test
public void testPlusMonthsLargePositive() throws Exception {
    LocalDate date = new LocalDate(2023, 10, 5);
    LocalDate result = date.plusMonths(1200);
    assertEquals("2100-10-05", result.toString());
}

@Test
public void testPlusMonthsLargeNegative() throws Exception {
    LocalDate date = new LocalDate(2023, 10, 5);
    LocalDate result = date.plusMonths(-1200);
    assertEquals("1900-10-05", result.toString());
}

@Test
public void testPlusMonthsEdgeCaseJanuary() throws Exception {
    LocalDate date = new LocalDate(2023, 1, 31);
    LocalDate result = date.plusMonths(1);
    assertEquals("2023-02-28", result.toString());
}

@Test
public void testPlusMonthsEdgeCaseFebruaryLeapYear() throws Exception {
    LocalDate date = new LocalDate(2024, 2, 29);
    LocalDate result = date.plusMonths(1);
    assertEquals("2024-03-29", result.toString());
}
